// repository-hygiene.yml: each check on a must-pass and a must-fail fixture (ADR-0017, ADR-0018, ADR-0021, ADR-0023;
// naming page §3). Fixtures that could be mistaken for real marks or secrets are assembled at run time.
import assert from 'node:assert/strict';
import { test } from 'node:test';
import { fixtureDir, fixtureRepo, git, runStep, writeFiles } from './harness.mjs';

const WORKFLOW = 'repository-hygiene.yml';
const TYPES = 'build chore ci docs feat fix perf refactor revert style test';
const LIMITS = { timeout: 15_000 };

const branch = (name, event = 'pull_request') =>
  runStep(WORKFLOW, 'check-branch-name', {
    cwd: fixtureDir('branch'),
    env: { NBX_EVENT_NAME: event, NBX_BRANCH: name, NBX_TYPES: TYPES, NBX_BOT_PREFIXES: 'dependabot/ release-please--' },
  });

test('branch names in <type>/<issue>-<slug> pass, with tool-mandated prefixes', LIMITS, () => {
  for (const name of ['feat/2-root-and-workflows', 'fix/97-oidc-callback', 'dependabot/npm_and_yarn/turbo-2.11.11']) {
    const result = branch(name);
    assert.equal(result.status, 0, `${name}\n${result.output}`);
  }
});

test('branch names outside <type>/<issue>-<slug> fail', LIMITS, () => {
  for (const name of ['main-fix', 'feat/root-and-workflows', 'feature/2-root', 'feat/2-Root', 'feat/2-root_and', 'feat/02-root']) {
    const result = branch(name);
    assert.equal(result.status, 1, `${name}\n${result.output}`);
    assert.match(result.output, /::error title=branch-name::/u);
  }
});

test('LF-only files pass the line-ending check', LIMITS, () => {
  const { dir, env } = fixtureRepo('lf', { 'notes.md': 'one\ntwo\n', 'logo.png': Buffer.from([0x89, 0x50, 0x0d, 0x0a, 0x00]) });
  const result = runStep(WORKFLOW, 'check-line-endings', { cwd: dir, baseEnv: env });
  assert.equal(result.status, 0, result.output);
});

test('a CR line ending fails the line-ending check', LIMITS, () => {
  const { dir, env } = fixtureRepo('crlf', { 'notes.md': 'one\r\ntwo\r\n' });
  const result = runStep(WORKFLOW, 'check-line-endings', { cwd: dir, baseEnv: env });
  assert.equal(result.status, 1, result.output);
  assert.match(result.output, /notes\.md/u);
});

test('lowercase paths and tool-mandated names pass the path check', LIMITS, () => {
  const { dir, env } = fixtureRepo('paths-ok', {
    'README.md': '# x\n',
    'packages/ui/src/order-card.tsx': 'export {};\n',
    '.claude/skills/nbx-release/SKILL.md': '# x\n',
    'apps/web/src/pages/[slug].astro': '---\n---\n',
  });
  const result = runStep(WORKFLOW, 'check-path-names', { cwd: dir, baseEnv: env, env: { NBX_PATH_EXCEPTIONS: '' } });
  assert.equal(result.status, 0, result.output);
});

test('a path with capitals or spaces fails the path check', LIMITS, () => {
  for (const path of ['packages/ui/OrderCard.tsx', 'docs/my notes.md', 'Apps/web/index.ts']) {
    const { dir, env } = fixtureRepo('paths-bad', { [path]: 'x\n' });
    const result = runStep(WORKFLOW, 'check-path-names', { cwd: dir, baseEnv: env, env: { NBX_PATH_EXCEPTIONS: '' } });
    assert.equal(result.status, 1, `${path}\n${result.output}`);
    assert.match(result.output, /::error title=path-names::/u);
  }
});

test('ordinary files pass the unsafe-file check, .env.example included', LIMITS, () => {
  const { dir, env } = fixtureRepo('safe', { '.env.example': 'NBX_DB_URL=\n', 'src/index.ts': 'export {};\n' });
  const result = runStep(WORKFLOW, 'check-unsafe-files', { cwd: dir, baseEnv: env });
  assert.equal(result.status, 0, result.output);
});

test('keys and environment files fail the unsafe-file check', LIMITS, () => {
  for (const path of ['deploy/server.pem', '.env', 'config/.env.production', 'certs/client.p12']) {
    const { dir, env } = fixtureRepo('unsafe', { [path]: 'FAKE\n' });
    const result = runStep(WORKFLOW, 'check-unsafe-files', { cwd: dir, baseEnv: env });
    assert.equal(result.status, 1, `${path}\n${result.output}`);
  }
});

// The forbidden marks, assembled so this file holds none of them.
const tool = ['Clau', 'de'].join('');
const trailer = ['Co', 'Authored', 'By'].join('-');

const authorship = (dir, env, extra = {}) =>
  runStep(WORKFLOW, 'check-authorship', {
    cwd: dir,
    baseEnv: env,
    env: { NBX_EVENT_NAME: 'push', NBX_ALLOW_LIST: '', NBX_PR_BODY: '', ...extra },
  });

test('prose about AI tools and our own tools pass the authorship check', LIMITS, () => {
  const { dir, env } = fixtureRepo('authorship-ok', {
    'package.json': JSON.stringify({ name: 'x', author: 'Nebulas X' }),
    'docs/assistant.md': `# The assistant\n\nZypher calls the ${tool} API to draft replies.\n`,
    'src/index.ts': '// Generated by tools/index.mjs from the registry.\nexport {};\n',
    'docs/rules.md': '- Built pages carry no `<meta name="generator">` tag.\n',
  });
  const result = authorship(dir, env);
  assert.equal(result.status, 0, result.output);
});

test('authorship fields, attribution comments, generator tags and trailers that name an AI tool fail', LIMITS, () => {
  const cases = [
    { 'package.json': JSON.stringify({ name: 'x', author: `${tool} Code` }) },
    { 'src/index.ts': `// Generated with ${tool} Code\nexport {};\n` },
    { 'site/index.html': '<html><head><meta name="generator" content="Astro"></head></html>\n' },
    { 'docs/page.md': `---\nauthor: ${tool}\n---\n# Page\n` },
  ];
  for (const files of cases) {
    const { dir, env } = fixtureRepo('authorship-bad', files);
    const result = authorship(dir, env);
    assert.equal(result.status, 1, `${Object.keys(files)[0]}\n${result.output}`);
    assert.match(result.output, /::error title=authorship::/u);
  }
  const { dir, env } = fixtureRepo('authorship-trailer', { 'a.txt': 'a\n' }, { commit: 'chore: start' });
  const base = git(dir, env, 'rev-parse', 'HEAD');
  writeFiles(dir, { 'b.txt': 'b\n' });
  git(dir, env, 'add', '-A');
  git(dir, env, 'commit', '-q', '-m', `feat: add b\n\n${trailer}: ${tool} <noreply@example.invalid>`);
  const head = git(dir, env, 'rev-parse', 'HEAD');
  const pr = { NBX_EVENT_NAME: 'pull_request', NBX_BASE_SHA: base, NBX_HEAD_SHA: head };
  const trailerResult = authorship(dir, env, pr);
  assert.equal(trailerResult.status, 1, trailerResult.output);
  assert.match(trailerResult.output, /commit [0-9a-f]{12}/u);
  const body = authorship(dir, env, { ...pr, NBX_HEAD_SHA: base, NBX_PR_BODY: `Summary\n\nGenerated with ${tool} Code` });
  assert.equal(body.status, 1, body.output);
  assert.match(body.output, /pull request body/u);
});

const DEPENDABOT_OK = `version: 2
updates:
  - package-ecosystem: npm
    directory: /
    schedule:
      interval: weekly
    cooldown:
      default-days: 7
  - package-ecosystem: github-actions
    directory: /
    schedule:
      interval: weekly
    cooldown:
      default-days: 7
      semver-major-days: 14
`;

const cooldown = (files, require = 'true') => {
  const dir = fixtureDir('cooldown');
  writeFiles(dir, files);
  return runStep(WORKFLOW, 'check-dependabot-cooldown', { cwd: dir, env: { NBX_REQUIRE_DEPENDABOT: require } });
};

test('a seven-day cooldown on every update entry passes', LIMITS, () => {
  const result = cooldown({ '.github/dependabot.yml': DEPENDABOT_OK });
  assert.equal(result.status, 0, result.output);
});

test('a missing, short or partial cooldown fails', LIMITS, () => {
  const fixtures = [
    DEPENDABOT_OK.replace(/    cooldown:\n      default-days: 7\n  - package/u, '  - package'),
    DEPENDABOT_OK.replaceAll('default-days: 7', 'default-days: 3'),
    DEPENDABOT_OK.replace('semver-major-days: 14', 'semver-patch-days: 1'),
    'version: 2\nupdates: []\n',
  ];
  for (const text of fixtures) {
    const result = cooldown({ '.github/dependabot.yml': text });
    assert.equal(result.status, 1, `${text}\n${result.output}`);
    assert.match(result.output, /::error title=dependabot-cooldown::/u);
  }
  const missing = cooldown({ 'README.md': '# x\n' });
  assert.equal(missing.status, 1, missing.output);
  const optional = cooldown({ 'README.md': '# x\n' }, 'false');
  assert.equal(optional.status, 0, optional.output);
});
